#
# check_codemap_counts.sh — issue §8 extension direction 5
#
# `docs/plans/codemap.md` §9 numbers are generated by
# `tools/gen_codemap_counts.py`; this gate fails when the committed table
# drifts from its derivations.
#
# Usage: tools/check_codemap_counts.sh

set -euo pipefail

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT_DIR"
. "$ROOT_DIR/tools/lib_python.sh"

STATUS=0
OUTPUT="$("$PYTHON" tools/gen_codemap_counts.py --check)" || STATUS=$?
printf '%s\n' "$OUTPUT"
[[ "$STATUS" -eq 0 ]] || exit "$STATUS"
echo "check_codemap_counts: OK"
